import {ceramicHold} from './ceramic-tools.js?v=51.0.0';
export const isStorage=p=>p?.type==='home'&&p.storageProfile?.reviewed===true;
// A stationary two-hand cradle: do not turn a wide box through its supporting hands.
export function storageHold(profile,time,reduced=false,rest){const pose=ceramicHold({heightIn:profile.heightIn,diameterIn:profile.widthIn},time,reduced,rest),half=profile.widthIn*2.54*.2+.08;pose.hands=pose.hands.map((h,i)=>{const a=rest?.[i]||{x:(i?1:-1)*10};return {...h,x:a.x+((i?1:-1)*half-a.x)*pose.reach};});return {...pose,turn:0};}
export function storageFactsHTML(p,esc){if(!isStorage(p))return '';const a=p.storageProfile;return `<section class="storage-facts frame-facts"><h4>Selected storage reference</h4><p>${esc(p.brand)} SKU <strong>${esc(p.referenceSKU)}</strong> · ${esc(p.colorName)} · ${p.sizes.map(esc).join(' / ')}.</p><p>${esc(a.dimensionNote)}</p><p>Opening: ${esc(a.opening)}. The inspection holds a closed, empty box. Shoes and photograph display contents are excluded. Storage does not equip clothing or expand your game bag.</p><p>${esc(p.sourceOfferNote)}</p><details><summary>Photograph & model notes</summary><p>${esc(a.photoBasis)}</p><p>Only this selected single-box format is stocked. Wall thickness, transparency, hardware and handling are original game interpretations. This is not a wearable size or a shoe-fit test.</p></details></section>`;}
